add_action( 'woocommerce_after_checkout_validation', 'perfectpixel_deny_checkout_pending_orders', 10, 2 );

function perfectpixel_deny_checkout_pending_orders( $data, $errors ) {
	$email = (string) ( $data['billing_email'] ?? '' );
	if ( '' === $email ) {
		return;
	}
	// The order being paid right now (a retry) must not block itself.
	$current = WC()->session ? absint( WC()->session->get( 'order_awaiting_payment' ) ) : 0;

	$pending = wc_get_orders(
		array(
			'billing_email' => $email,
			'status'        => array( 'wc-pending' ),
			'exclude'       => $current ? array( $current ) : array(),
			'limit'         => 1,
			'return'        => 'ids',
		)
	);
	if ( $pending ) {
		$errors->add( 'perfectpixel_pending_order', esc_html( '{{pending_message}}' ) );
	}
}
